import { lowPower } from "../animations/core/manager.js";
import { profile as p } from "../data/profile.js";
import { boot, lazyScene } from "./shared.js";
import { icon } from "../components/icons.js";
import { esc, profileLinks } from "../components/utils.js";
import { copyText } from "../components/toast.js";
boot(
  "contact",
  `<section class="contact-page"><div id="interference" class="scene contact-field" aria-hidden="true"></div><div><div class="contact-card"><p class="eyebrow page-kicker">${p.contact.eyebrow}</p><h1>${p.contact.title}</h1><p>${p.contact.description}</p><div class="contact-details"><p class="eyebrow">${p.contact.emailLabel}</p><div class="email-row"><a class="email-link" href="mailto:${p.email}">${p.email}</a><button id="copy-email" class="icon-button" aria-label="${p.ui.copyEmail}" title="${p.ui.copyEmail}">${icon("copy")}</button></div><div class="contact-meta"><div><p class="eyebrow">${p.contact.locationLabel}</p><p>${p.location}</p></div><div><p class="eyebrow">${p.contact.profilesLabel}</p>${profileLinks()}</div></div>${p.phone ? `<p>${esc(p.phone)}</p>` : ""}<p class="contact-references">${p.contact.references}</p></div></div><p class="contact-field-caption mono">${p.contact.fieldLabel}</p><p class="contact-field-caption contact-field-hint">${p.contact.fieldHint}</p></div></section>`,
);
document
  .querySelector("#copy-email")
  .addEventListener("click", () => copyText(p.email, p.ui.emailCopied));
lazyScene(
  "interference",
  () =>
    lowPower
      ? import("../animations/interferenceLite.js")
      : import("../animations/interference.js"),
  "interference",
);
